<script setup lang="ts">
import { onMounted } from 'vue'
import { RouterLink,RouterView,useRoute } from 'vue-router'
import { PhArrowsClockwise,PhBlueprint,PhGitBranch,PhListMagnifyingGlass,PhUploadSimple,PhWarning } from '@phosphor-icons/vue'
import { useAnalysis } from './composables/useAnalysis'
const analysis=useAnalysis();const route=useRoute();onMounted(analysis.ensureLoaded)
</script>
<template><div class="app-shell"><aside class="rail"><RouterLink class="brand" :to="{name:'map'}" aria-label="CodeAtlas 首页"><PhBlueprint :size="25" weight="duotone"/><span>CodeAtlas</span></RouterLink><nav aria-label="主要导航"><RouterLink :to="{name:'map'}"><PhGitBranch :size="19"/><span>架构图谱</span></RouterLink><RouterLink :to="{name:'risks'}"><PhWarning :size="19"/><span>风险诊断</span></RouterLink><RouterLink :to="{name:'files'}"><PhListMagnifyingGlass :size="19"/><span>热点文件</span></RouterLink><RouterLink :to="{name:'repository'}"><PhUploadSimple :size="19"/><span>代码接入</span></RouterLink></nav><div class="rail-foot"><span class="status-dot"></span><span>分析引擎在线</span></div></aside><main><header class="topbar"><div v-if="analysis.data.value" class="repo-meta"><strong>{{analysis.data.value.repository.name}}</strong><span>{{analysis.data.value.repository.branch}}</span><code>{{analysis.data.value.repository.commit}}</code><em>{{analysis.data.value.repository.synthetic?'模拟仓库':'真实扫描'}}</em></div><div v-else class="repo-meta skeleton-line"></div><div class="route-context"><span>{{String(route.meta.title||'架构图谱')}}</span><button v-if="route.name!=='repository'" class="scan-button" :disabled="analysis.scanning.value||analysis.loading.value" @click="analysis.scan"><PhArrowsClockwise :class="{spinning:analysis.scanning.value}" :size="17"/>{{analysis.scanning.value?'正在扫描':'重新扫描'}}</button></div></header><div v-if="analysis.error.value&&route.name!=='repository'" class="error-banner" role="alert"><span>{{analysis.error.value}}</span><button @click="analysis.load()">重试</button></div><section v-if="analysis.loading.value&&!analysis.data.value&&route.name!=='repository'" class="loading-layout" aria-label="正在加载"><div class="skeleton graph-skeleton"></div><div class="skeleton panel-skeleton"></div></section><RouterView v-else/></main></div></template>
